#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

typedef struct { int data[128]; size_t size; } Stack;
static int push(Stack *stack,int value){
    if(stack->size==128)return 0;stack->data[stack->size++]=value;return 1;
}
static int pop(Stack *stack,int *out){
    if(!stack->size)return 0;*out=stack->data[--stack->size];return 1;
}
static int top(const Stack *stack,int *out){
    if(!stack->size)return 0;*out=stack->data[stack->size-1];return 1;
}
int main(void) {
Stack stack={0};int q;if(scanf("%d",&q)!=1 || q<0 || q>128)return 1;for(int i=0;i<q;++i){char c;int x;if(scanf(" %c",&c)!=1)return 1;if(c=='P'){if(scanf("%d",&x)!=1||!push(&stack,x))return 1;}else if(c=='O'||c=='T'){int ok=c=='O'?pop(&stack,&x):top(&stack,&x);if(ok)printf("%d\n",x);else puts("ПУСТО");}else return 1;}
return 0;
}
